def choose_move(observation):
    # Defensive defaults
    x = observation.get("agent_x", 0)
    y = observation.get("agent_y", 0)
    target = observation.get("target", None)
    width = observation.get("width", 0)
    height = observation.get("height", 0)

    # Try to use a simple robust policy:
    # If a target is provided, move toward it within bounds.
    if isinstance(target, dict):
        tx = target.get("x", x)
        ty = target.get("y", y)
        dx = 0
        dy = 0
        if tx > x:
            dx = 1
        elif tx < x:
            dx = -1
        else:
            dx = 0
        if ty > y:
            dy = 1
        elif ty < y:
            dy = -1
        else:
            dy = 0

        # Clip to [-1,0,1]
        dx = max(-1, min(1, dx))
        dy = max(-1, min(1, dy))
        # If still at target, no move
        if dx == 0 and dy == 0:
            return [0, 0]
        return [dx, dy]

    # Fallback simple heuristics: move toward center of map to stay safe/cover
    cx = width // 2
    cy = height // 2

    dx = 0
    dy = 0
    if cx > x:
        dx = 1
    elif cx < x:
        dx = -1
    else:
        dx = 0

    if cy > y:
        dy = 1
    elif cy < y:
        dy = -1
    else:
        dy = 0

    # If near edge, bias to stay inside
    if x + dx < 0:
        dx = 0
    if x + dx >= width:
        dx = 0
    if y + dy < 0:
        dy = 0
    if y + dy >= height:
        dy = 0

    return [dx, dy]

